insert into v3_check select 4, 'V4 FINGERPRINT data (must equal the snapshot)', 'COMPARE', (select md5(string_agg(t || '=' || n, ',' order by t)) from (select c.relname::text t, (xpath('/row/n/text()', query_to_xml(format('select count(*) as n from public.%I', c.relname), false, true, '')))[1]::text n from pg_catalog.pg_class c where c.relnamespace = 'public'::regnamespace and c.relkind = 'r' and c.relname not in ('audit_log', 'business_exemptions', 'business_trials', 'charges', 'payments', 'staff_permissions', 'app_settings', 'reminder_log', 'notifications')) x);
insert into v3_check select 4, 'V4 FINGERPRINT settings (must equal the snapshot)', 'COMPARE', (select md5(string_agg(key || '=' || value, ',' order by key)) from public.app_settings where key not in ('grace_days', 'launch_at', 'trial_days'));
insert into v3_check select 4, 'V4 v3 settings: trial 30, grace 7, no launch date; subscriptions_required off', case when coalesce((select string_agg(key || '=' || value, ',' order by key) from public.app_settings where key in ('grace_days', 'launch_at', 'trial_days')), '') = 'grace_days=7,launch_at=,trial_days=30' and coalesce((select value from public.app_settings where key = 'subscriptions_required'), 'false') = 'false' then 'PASS' else 'FAIL' end, coalesce((select string_agg(key || '=' || value, ',' order by key) from public.app_settings where key in ('grace_days', 'launch_at', 'trial_days')), '');
insert into v3_check select 4, 'V4 v3 tables empty (nothing has used them yet)', case when not exists (select 1 from public.audit_log) and not exists (select 1 from public.business_exemptions) and not exists (select 1 from public.business_trials) and not exists (select 1 from public.charges) and not exists (select 1 from public.payments) and not exists (select 1 from public.staff_permissions) then 'PASS' else 'FAIL' end, null;
insert into v3_check select 6, 'V6 RLS on every public table, no bypass for anon/authenticated', case when not exists (select 1 from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relkind = 'r' and not c.relrowsecurity) and not exists (select 1 from pg_roles where rolname in ('anon','authenticated') and rolbypassrls) then 'PASS' else 'FAIL' end, null;
insert into v3_check select 6, 'V6 private photos bucket still private', case when exists (select 1 from storage.buckets where id = 'photos-private' and not public) then 'PASS' else 'FAIL' end, null;
-- V6 isolation, as a signed-in stranger and as a visitor (role switched inside this transaction only)
do $iso$
declare n1 int; n2 int; n3 int; n4 int; ok boolean; vis text;
begin
  perform set_config('request.jwt.claim.sub', '00000000-0000-4000-8000-00000000c1a5', true);
  execute 'set local role authenticated';
  select count(*) into n1 from public.business_charges();
  select count(*) into n2 from public.my_charges();
  select count(*) into n3 from public.my_ledger_businesses();
  select count(*) into n4 from public.admin_business_access();
  begin perform 1 from public.charges limit 1; ok := false; exception when insufficient_privilege then ok := true; end;
  execute 'reset role';
  insert into v3_check values (6, 'V6 a signed-in stranger sees no charges, no businesses, no admin list; no direct table access', case when n1 + n2 + n3 + n4 = 0 and ok then 'PASS' else 'FAIL' end, format('charges=%s mine=%s businesses=%s admin=%s direct_denied=%s', n1, n2, n3, n4, ok));
  execute 'set local role anon';
  begin perform public.create_charge(null, null, 'x', 'y', 1); ok := false; exception when insufficient_privilege then ok := true; end;
  execute 'reset role';
  insert into v3_check values (6, 'V6 a visitor cannot call the ledger functions', case when ok then 'PASS' else 'FAIL' end, null);
  execute 'set local role anon';
  select (select md5(concat_ws('|', (select string_agg(id::text, ',' order by id) from public.teachers), (select string_agg(id::text, ',' order by id) from public.institutes), (select string_agg(id::text, ',' order by id) from public.offerings)))) into vis;
  execute 'reset role';
  insert into v3_check values (5, 'V5 FINGERPRINT visible to visitors (must equal the snapshot)', 'COMPARE', vis);
end $iso$;
select check_name, result, detail from v3_check order by n, check_name;
rollback;
